head.script:
(function() {
    function updateCartTitle() {
        var cartTitle = document.querySelector('.header-cart-title');
        if (cartTitle && cartTitle.innerText.includes('购物车')) {
            cartTitle.innerText = cartTitle.innerText.replace('购物车', 'Cart');
        }
    }

    // 页面加载时执行
    updateCartTitle();

    // DOM 加载完成后执行
    document.addEventListener('DOMContentLoaded', updateCartTitle);

    // 延迟执行（确保动态内容加载完）
    setTimeout(updateCartTitle, 500);
    setTimeout(updateCartTitle, 1000);
    setTimeout(updateCartTitle, 2000);

    // 监听购物车更新
    if (typeof jQuery !== 'undefined') {
        jQuery(document.body).on('added_to_cart removed_from_cart updated_cart_totals wc_fragments_refreshed wc_fragments_loaded', updateCartTitle);
    }

    // MutationObserver 监听 DOM 变化
    var observer = new MutationObserver(updateCartTitle);
    observer.observe(document.body, { childList: true, subtree: true });
})();

body.script:
(function () {
	var c = document.body.className;
	c = c.replace(/woocommerce-no-js/, 'woocommerce-js');
	document.body.className = c;
})();

